cat > merge.py <<'EOF'
import json
import pandas as pd

FIELD_MAP = {
    "user_id": "user_id", "id": "user_id", "userId": "user_id",
    "email": "email", "email_address": "email",
    "full_name": "name", "name": "name", "userName": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "status": "status", "is_active": "status", "active": "status",
}
FIELDS = ["name", "email", "created_date", "status"]
SOURCES = ["source_a", "source_b", "source_c"]  # priority order


def to_bool(v):
    if isinstance(v, str):
        return v.strip().lower() in ("true", "1", "yes", "y", "t")
    return bool(v)


def normalize(field, v):
    if v is None or (not isinstance(v, (list, dict)) and pd.isna(v)):
        return None
    if field == "user_id":
        return int(v)
    if field == "created_date":
        return pd.to_datetime(v).strftime("%Y-%m-%d")
    if field == "status":
        if isinstance(v, str) and v.strip().lower() not in ("true", "false", "1", "0", "yes", "no"):
            return v.strip()
        return "active" if to_bool(v) else "inactive"
    return str(v).strip()


def load(src, df):
    recs = {}
    for row in df.to_dict(orient="records"):
        rec = {}
        for k, v in row.items():
            if k in FIELD_MAP:
                rec[FIELD_MAP[k]] = normalize(FIELD_MAP[k], v)
        recs[rec["user_id"]] = rec
    return recs


data = {
    "source_a": load("source_a", pd.DataFrame(json.load(open("/data/source_a/users.json")))),
    "source_b": load("source_b", pd.read_csv("/data/source_b/users.csv", dtype=str)),
    "source_c": load("source_c", pd.read_parquet("/data/source_c/users.parquet")),
}

all_ids = sorted(set().union(*(d.keys() for d in data.values())))
rows, conflicts = [], []
for uid in all_ids:
    out = {"user_id": uid}
    for f in FIELDS:
        vals = {s: data[s][uid].get(f) for s in SOURCES if uid in data[s] and data[s][uid].get(f) is not None}
        selected = next(iter(vals.values()), None)
        out[f] = selected
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": selected})
    rows.append(out)

df = pd.DataFrame(rows, columns=["user_id"] + FIELDS)
df["user_id"] = df["user_id"].astype("int64")
df.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json", "w"), indent=2)
print(df); print(df.dtypes)
EOF
./envcp merge.py :/app/merge.py && ./envrun 'cd /app && python3 merge.py && cat conflicts.json'
